import React, { useState, useEffect } from "react";
import axios from "axios";

const Dashboard = ({ userId }) => {
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchDashboardData = async () => {
      if (!userId) {
        setError("No userId provided");
        setLoading(false);
        return;
      }
      try {
        const response = await axios.get("http://localhost:5000/dashboard", {
          headers: { "user-id": userId },
        });
        setDashboardData(response.data);
      } catch (err) {
        const errorMessage = err.response
          ? `Server error: ${err.response.status} - ${JSON.stringify(
              err.response.data
            )}`
          : `Network error: ${err.message}`;
        setError(`Failed to fetch dashboard data: ${errorMessage}`);
      } finally {
        setLoading(false);
      }
    };
    fetchDashboardData();
  }, [userId]);

  if (loading) return <p style={styles.message}>Loading...</p>;

  if (error) return <p style={{ ...styles.message, color: "red" }}>{error}</p>;

  if (!dashboardData || !dashboardData.user)
    return <p style={styles.message}>No dashboard data available</p>;

  const { user, wishlist, recentActivity } = dashboardData;

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>🏠 My Dashboard</h2>

      <section style={styles.section}>
        <h3 style={styles.subTitle}>👤 Welcome, {user.full_name || "Guest"}</h3>
        <p style={styles.info}>📧 Email: {user.email || "N/A"}</p>
      </section>

      <section style={styles.section}>
        <h3 style={styles.subTitle}>💖 My Wishlist</h3>
        {wishlist && wishlist.length > 0 ? (
          <div style={styles.cardGrid}>
            {wishlist.map((house) => (
              <div key={house.id} style={styles.card}>
                <img
                  src={`http://localhost:5000${house.images?.[0]}`}
                  alt="House"
                  style={styles.image}
                  onError={(e) => (e.target.src = "/fallback-image.jpg")}
                />
                <div>
                  <h4 style={styles.cardTitle}>{house.address || "N/A"}</h4>
                  <p style={styles.price}>💰 ${house.price || "N/A"}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p style={styles.emptyMessage}>No items in your wishlist</p>
        )}
      </section>

      <section style={styles.section}>
        <h3 style={styles.subTitle}>🕒 Recent Activity</h3>
        {recentActivity && recentActivity.length > 0 ? (
          <div style={styles.cardGrid}>
            {recentActivity.map((activity, index) => (
              <div key={index} style={styles.card}>
                <h4 style={styles.cardTitle}>{activity.address || "N/A"}</h4>
                <p style={styles.price}>💰 ${activity.price || "N/A"}</p>
              </div>
            ))}
          </div>
        ) : (
          <p style={styles.emptyMessage}>No recent activity</p>
        )}
      </section>
    </div>
  );
};

const styles = {
  container: {
    padding: "30px",
    backgroundColor: "#f5f7fa",
    minHeight: "100vh",
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    color: "#333",
  },
  title: {
    textAlign: "center",
    marginBottom: "30px",
    fontSize: "2.2rem",
    color: "#1a1a1a",
  },
  section: {
    marginBottom: "40px",
  },
  subTitle: {
    fontSize: "1.6rem",
    marginBottom: "15px",
    color: "#2c3e50",
  },
  info: {
    fontSize: "1rem",
    marginBottom: "10px",
  },
  message: {
    color: "black",
    textAlign: "center",
    marginTop: "40px",
    fontSize: "1.2rem",
  },
  emptyMessage: {
    color: "#777",
    fontStyle: "italic",
    fontSize: "1rem",
  },
  cardGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
    gap: "20px",
  },
  card: {
    backgroundColor: "#ffffff",
    borderRadius: "12px",
    padding: "20px",
    boxShadow: "0 4px 12px rgba(0, 0, 0, 0.08)",
    display: "flex",
    flexDirection: "column",
    alignItems: "flex-start",
    transition: "transform 0.2s",
  },
  image: {
    width: "100%",
    height: "160px",
    objectFit: "cover",
    borderRadius: "8px",
    marginBottom: "15px",
  },
  cardTitle: {
    fontSize: "1.1rem",
    fontWeight: "bold",
    marginBottom: "8px",
    color: "#34495e",
  },
  price: {
    fontSize: "1rem",
    color: "#27ae60",
  },
};

export default Dashboard;
